<script setup>import{onMounted,ref}from'vue';import api from '../services/api';const items=ref([]);const load=async()=>items.value=(await api.get('/notifications')).data.data.data;onMounted(load);const read=async item=>{await api.post(`/notifications/${item.id}/read`);load()}</script><template><section><div class="page-heading"><div><p class="eyebrow">ALERTS</p><h2>নোটিফিকেশন ও সতর্কতা</h2><p>কম স্টক, বকেয়া এবং গুরুত্বপূর্ণ কার্যক্রমের আপডেট।</p></div></div><div class="panel notification-list"><article v-for="item in items" :key="item.id" :class="{unread:!item.read_at}" @click="read(item)"><span class="metric-icon amber">!</span><div><strong>{{item.title}}</strong><p>{{item.body}}</p><small>{{item.created_at}}</small></div></article><p v-if="!items.length" class="empty">এখনও কোনো নোটিফিকেশন নেই।</p></div></section></template>
